// === Lab-0: Build OpenAI Responses API request ===
// IMPORTANT: Replace YOUR_API_KEY_HERE with your real key.
// Tip: For teaching labs, prefer env var (process.env) or credential storage.

const apiKey = "YOUR_API_KEY_HERE";

msg.method = "POST";
msg.url = "https://api.openai.com/v1/responses";

msg.headers = {
  "Authorization": `Bearer ${apiKey}`,
  "Content-Type": "application/json"
};

msg.payload = {
  model: "gpt-4.1-mini",
  input: String(msg.payload || "")
};

return msg;

// === Lab-0: Extract assistant text from Responses API ===
// Handle success + useful error messages

const res = msg.payload;

// If OpenAI returns an error shape
if (res && res.error) {
  msg.payload = `OpenAI error: ${res.error.message || JSON.stringify(res.error)}`;
  return msg;
}

try {
  // Typical structure: output[0].content[0].text
  const text = res?.output?.[0]?.content?.[0]?.text;

  if (typeof text === "string" && text.length > 0) {
    msg.payload = text;
  } else {
    // Fallback: show a compact view for debugging
    msg.payload = "No text found. Raw response:\n" + JSON.stringify(res, null, 2);
  }

  return msg;
} catch (e) {
  msg.payload = "Parse error: " + e.message + "\nRaw:\n" + JSON.stringify(res, null, 2);
  return msg;
}
